const updateFinancialGoal = `-- name: UpdateFinancialGoal :exec
UPDATE financial_goals SET
    portfolio_list_id = $2, name = $3, goal_type = $4, target_amount = $5, target_date = $6,
    base_currency = $7, starting_capital = $8, monthly_contribution = $9,
    annual_contribution_growth = $10, inflation_assumption = $11, risk_profile = $12,
    expected_annual_return = $13, status = $14, updated_at = $15
WHERE id = $1
`

type UpdateFinancialGoalParams struct {
	ID                       uuid.UUID
	PortfolioListID          uuid.UUID
	Name                     string
	GoalType                 string
	TargetAmount             float64
	TargetDate               time.Time
	BaseCurrency             string
	StartingCapital          float64
	MonthlyContribution      float64
	AnnualContributionGrowth float64
	InflationAssumption      float64
	RiskProfile              string
	ExpectedAnnualReturn     float64
	Status                   string
	UpdatedAt                *time.Time
}

// Fluent save of an updated model: every assigned field plus updated_at.
func (q *Queries) UpdateFinancialGoal(ctx context.Context, arg UpdateFinancialGoalParams) error {
	_, err := q.db.Exec(ctx, updateFinancialGoal,
		arg.ID,
		arg.PortfolioListID,
		arg.Name,
		arg.GoalType,
		arg.TargetAmount,
		arg.TargetDate,
		arg.BaseCurrency,
		arg.StartingCapital,
		arg.MonthlyContribution,
		arg.AnnualContributionGrowth,
		arg.InflationAssumption,
		arg.RiskProfile,
		arg.ExpectedAnnualReturn,
		arg.Status,
		arg.UpdatedAt,
	)
	return err
}

